import type { Question } from '../../lib/types'

export const storage_performance_questions: Question[] = [
  { id: 'd3-sto-001', domain: 3, topics: ['EFS', 'performance mode', 'throughput mode'], type: 'single', stem: 'An EFS file system serving an HPC cluster with thousands of files per second is experiencing high latency. What performance mode reduces latency for IOPS-intensive workloads?', options: [{ id: 'A', text: 'General Purpose performance mode (default) — low latency but per-operation overhead' }, { id: 'B', text: 'Max I/O performance mode — optimized for maximum aggregate throughput and IOPS, slightly higher latency per operation' }, { id: 'C', text: 'Bursting throughput mode' }, { id: 'D', text: 'Provisioned throughput mode' }], correct: ['A'], explanation: 'General Purpose performance mode has lower per-operation latency — best for latency-sensitive workloads. Max I/O mode supports higher aggregate IOPS for parallelized workloads (HPC, Hadoop) but has slightly higher per-operation latency. For the scenario asking about reducing latency, General Purpose is actually the answer.', distractors: { B: 'Max I/O provides higher aggregate throughput but slightly higher per-operation latency — choose for throughput over latency.', C: 'Bursting throughput mode controls the throughput amount — not latency.', D: 'Provisioned throughput mode sets guaranteed throughput — not latency optimization.' } },
  { id: 'd3-sto-002', domain: 3, topics: ['EFS', 'elastic throughput'], type: 'single', stem: 'An EFS file system has unpredictable throughput requirements — sometimes very high, sometimes very low. What EFS throughput mode handles variable workloads automatically?', options: [{ id: 'A', text: 'Bursting throughput — scales with file system size' }, { id: 'B', text: 'Elastic throughput — automatically scales to match workload demand, pay per GB of data transferred' }, { id: 'C', text: 'Provisioned throughput — reserve a fixed amount' }, { id: 'D', text: 'Max I/O mode' }], correct: ['B'], explanation: 'EFS Elastic Throughput (available since 2022) automatically scales throughput up and down based on actual workload requirements. No capacity planning needed. Charges based on GB of data transferred, making it cost-efficient for variable workloads.', distractors: { A: 'Bursting scales with file system size and accumulates credits — doesn\'t automatically match arbitrary workload spikes.', C: 'Provisioned throughput reserves capacity — you pay for the reserved amount even when not used.', D: 'Max I/O is a performance mode (latency vs. throughput trade-off) — not a throughput scaling mode.' } },
  { id: 'd3-sto-003', domain: 3, topics: ['S3', 'performance', 'prefix', 'parallelism'], type: 'single', stem: 'An application uploads thousands of files per second to S3. All files are prefixed with the date (e.g., 2026-07-27-file001). Performance is hitting S3 limits. How should the key namespace be designed for maximum throughput?', options: [{ id: 'A', text: 'Use random characters at the beginning of the key prefix to distribute across S3 partitions' }, { id: 'B', text: 'Use date prefixes as-is — S3 handles partitioning automatically now (since 2018)' }, { id: 'C', text: 'Use a single prefix for all files' }, { id: 'D', text: 'Limit to one upload per second' }], correct: ['B'], explanation: 'Since July 2018, S3 supports 3,500 PUT/COPY/POST/DELETE and 5,500 GET/HEAD requests per second per prefix. S3 automatically scales to handle high request rates. The old advice about random prefixes is outdated — date prefixes are fine.', distractors: { A: 'Randomizing prefixes was the old workaround — no longer necessary since S3 auto-scales per prefix.', C: 'A single prefix means all requests go to one partition — though S3 auto-scales, using multiple prefixes naturally distributes load.', D: 'One upload per second would be extremely limiting — S3 handles thousands per prefix.' } },
  { id: 'd3-sto-004', domain: 3, topics: ['FSx', 'Lustre', 'HPC'], type: 'single', stem: 'An HPC simulation requires a parallel file system with sub-millisecond latency and hundreds of GB/s throughput. Which AWS storage service provides this?', options: [{ id: 'A', text: 'EFS with Max I/O mode' }, { id: 'B', text: 'Amazon FSx for Lustre — purpose-built parallel file system for HPC, ML, and analytics; sub-millisecond latency' }, { id: 'C', text: 'S3 with high-bandwidth endpoints' }, { id: 'D', text: 'EBS io2 Block Express' }], correct: ['B'], explanation: 'FSx for Lustre is the AWS implementation of the open-source Lustre parallel file system. Provides sub-millisecond latency and throughput up to hundreds of GB/s. Integrates with S3 for data import/export. Used for ML training, HPC, genomics.', distractors: { A: 'EFS Max I/O provides high aggregate IOPS but not sub-millisecond latency or Lustre-level throughput.', C: 'S3 is object storage — not a file system with Lustre-level performance.', D: 'EBS io2 BE is high-performance block storage but is tied to a single EC2 instance, not shared across HPC nodes.' } },
  { id: 'd3-sto-005', domain: 3, topics: ['S3', 'multipart upload', 'parallel'], type: 'single', stem: 'What is the recommended minimum file size to start using S3 multipart upload for best performance?', options: [{ id: 'A', text: '5 MB' }, { id: 'B', text: '100 MB — AWS recommends multipart upload for files larger than 100 MB' }, { id: 'C', text: '5 GB (required for files over 5 GB)' }, { id: 'D', text: '1 TB' }], correct: ['B'], explanation: 'AWS recommends S3 multipart upload for files over 100 MB for improved performance (parallel uploads). It\'s REQUIRED for files over 5 GB (max single PUT size). Min part size is 5 MB (except the last part).', distractors: { A: '5 MB is the minimum part size for multipart upload — not the recommendation threshold for when to use it.', C: '5 GB is the mandatory threshold — multipart is recommended at 100 MB for performance.', D: 'No one waits until 1 TB to use multipart upload — performance benefits start at 100 MB.' } },
  { id: 'd3-sto-006', domain: 3, topics: ['FSx', 'Windows', 'SMB'], type: 'single', stem: 'A Windows application requires a fully managed Windows file server with Active Directory integration and SMB protocol support. What AWS service provides this?', options: [{ id: 'A', text: 'Amazon EFS (NFS protocol)' }, { id: 'B', text: 'Amazon FSx for Windows File Server — managed Windows file system with AD integration, SMB, NTFS, DFS' }, { id: 'C', text: 'Amazon S3' }, { id: 'D', text: 'AWS Storage Gateway (file gateway)' }], correct: ['B'], explanation: 'FSx for Windows File Server provides a fully managed native Windows file system: SMB protocol, NTFS, Active Directory integration, Windows ACLs, VSS (shadow copies), DFS Namespaces. Drop-in replacement for on-premises Windows file servers.', distractors: { A: 'EFS is NFS-based and Linux/POSIX — not native Windows SMB.', C: 'S3 is object storage — not a Windows-native file system.', D: 'Storage Gateway File Gateway provides NFS/SMB access but caches locally — FSx is a fully managed file server.' } },
  { id: 'd3-sto-007', domain: 3, topics: ['S3', 'Glacier', 'restore', 'performance'], type: 'single', stem: 'An application restores data from S3 Glacier Flexible Retrieval every night using Bulk retrieval (cheapest). Occasionally, urgent requests require faster access. How can the application support both cost-optimized and urgent access patterns?', options: [{ id: 'A', text: 'Always use Expedited retrieval — more expensive but always fast' }, { id: 'B', text: 'Use Bulk for nightly batch jobs; switch to Expedited retrieval for urgent ad-hoc requests (pay premium only when needed)' }, { id: 'C', text: 'Move all data to S3 Standard for faster access' }, { id: 'D', text: 'Use S3 Glacier Instant Retrieval for all data' }], correct: ['B'], explanation: 'Glacier Flexible Retrieval allows choosing retrieval tier per request. Use Bulk (5-12 hours, cheapest) for predictable batch jobs. Use Expedited (1-5 minutes, most expensive) only for urgent ad-hoc requests. Pay appropriately for each use case.', distractors: { A: 'Expedited for all requests unnecessarily increases costs for batch jobs.', C: 'Moving to S3 Standard is 30x+ more expensive than Glacier for archival data.', D: 'Glacier Instant Retrieval costs more than Glacier Flexible Retrieval — appropriate for data accessed regularly, not bulk archival.' } },
  { id: 'd3-sto-008', domain: 3, topics: ['FSx', 'ONTAP', 'NFS', 'SMB', 'hybrid'], type: 'single', stem: 'A company runs applications on both Linux (NFS) and Windows (SMB) that need to access the same file data simultaneously. Which FSx offering supports both protocols on the same file system?', options: [{ id: 'A', text: 'FSx for Windows File Server' }, { id: 'B', text: 'FSx for Lustre' }, { id: 'C', text: 'FSx for NetApp ONTAP — supports NFS, SMB, and iSCSI on the same managed file system' }, { id: 'D', text: 'EFS' }], correct: ['C'], explanation: 'FSx for NetApp ONTAP supports NFS (Linux), SMB (Windows), and iSCSI simultaneously on the same file system. Also supports data management features (snapshots, replication, tiering). Great for mixed-OS environments.', distractors: { A: 'FSx for Windows File Server is SMB-only — Linux clients would need SMB mounts.', B: 'FSx for Lustre is POSIX/NFS — not native SMB.', D: 'EFS supports NFS only — not SMB.' } },
  { id: 'd3-sto-009', domain: 3, topics: ['EBS', 'gp3', 'throughput baseline'], type: 'single', stem: 'A gp3 EBS volume is provisioned at 500 GB. What is the default throughput without additional configuration?', options: [{ id: 'A', text: '250 MB/s' }, { id: 'B', text: '125 MB/s — gp3 baseline throughput regardless of size' }, { id: 'C', text: '1,000 MB/s' }, { id: 'D', text: 'Throughput scales with size on gp3' }], correct: ['B'], explanation: 'gp3 provides 125 MB/s baseline throughput for any volume size (configurable up to 1,000 MB/s). Unlike gp2 where throughput scales with size, gp3 baseline is fixed regardless of size, with the ability to independently provision more.', distractors: { A: '250 MB/s is not the gp3 baseline — 125 MB/s is correct.', C: '1,000 MB/s is the maximum gp3 throughput (when provisioned) — not the default.', D: 'gp3 throughput does NOT scale with size — it\'s a fixed baseline (key differentiator from gp2).' } },
  { id: 'd3-sto-010', domain: 3, topics: ['S3', 'acceleration', 'transfer'], type: 'single', stem: 'A company in Australia frequently uploads 10 GB files to an S3 bucket in us-east-1 and experiences slow upload speeds. What AWS feature can improve upload speed?', options: [{ id: 'A', text: 'S3 Multipart Upload alone' }, { id: 'B', text: 'S3 Transfer Acceleration — routes uploads through CloudFront edge locations, using AWS backbone for the long-haul path' }, { id: 'C', text: 'CloudFront distribution for uploads' }, { id: 'D', text: 'Direct Connect from Australia' }], correct: ['B'], explanation: 'S3 Transfer Acceleration routes uploads through the nearest CloudFront edge location, using the AWS backbone network for the long-haul path to S3. For users far from the S3 bucket region, this can be 60-500% faster than direct S3 uploads.', distractors: { A: 'Multipart Upload helps with reliability and parallel uploads — but still uses the direct internet path to S3.', C: 'CloudFront distributes content from caches — it doesn\'t accelerate S3 uploads (it\'s used for downloads).', D: 'Direct Connect provides dedicated bandwidth but requires physical hardware installation — not a quick fix.' } },
  { id: 'd3-sto-011', domain: 3, topics: ['Storage Gateway', 'file gateway', 'hybrid'], type: 'single', stem: 'An on-premises application reads and writes files using NFS. The company wants to store files in S3 without changing the application. What service enables this seamlessly?', options: [{ id: 'A', text: 'AWS DataSync' }, { id: 'B', text: 'AWS Storage Gateway File Gateway — presents NFS/SMB interface on-premises, stores objects in S3' }, { id: 'C', text: 'Amazon EFS' }, { id: 'D', text: 'AWS Transfer Family' }], correct: ['B'], explanation: 'Storage Gateway File Gateway runs on-premises (virtual or hardware appliance) and presents NFS/SMB shares. Files written are transparently stored as S3 objects. Applications see a normal file share — no code changes needed.', distractors: { A: 'DataSync is a data migration/transfer tool — not a persistent NFS mount for ongoing application I/O.', C: 'EFS is a cloud-native NFS service — on-premises access requires VPN/Direct Connect and doesn\'t provide S3 integration.', D: 'Transfer Family provides SFTP/FTP access to S3 — not NFS for on-premises applications.' } },
  { id: 'd3-sto-012', domain: 3, topics: ['Storage Gateway', 'volume gateway', 'cached', 'stored'], type: 'single', stem: 'An on-premises server has 50 TB of data and limited local storage. The company wants to keep frequently accessed data local and tier the rest to S3. Which Storage Gateway mode provides this?', options: [{ id: 'A', text: 'Volume Gateway in stored volumes mode' }, { id: 'B', text: 'Volume Gateway in cached volumes mode — primary data in S3, frequently accessed data cached locally' }, { id: 'C', text: 'File Gateway' }, { id: 'D', text: 'Tape Gateway' }], correct: ['B'], explanation: 'Cached volumes mode: all data stored in S3, only frequently accessed data kept in local cache. Allows local storage to be smaller than total data. Application sees iSCSI block volumes — no change to application.', distractors: { A: 'Stored volumes mode keeps all primary data on-premises and asynchronously backs up to S3 — doesn\'t solve the "limited local storage" problem.', C: 'File Gateway presents NFS/SMB file shares — different use case from block storage volumes.', D: 'Tape Gateway is for backup applications using VTL — not for general block storage tiering.' } },
  { id: 'd3-sto-013', domain: 3, topics: ['DataSync', 'migration', 'performance'], type: 'single', stem: 'A company needs to migrate 100 TB of data from on-premises NFS to Amazon EFS. They need to complete the migration within days while maintaining bandwidth controls. What service handles this efficiently?', options: [{ id: 'A', text: 'AWS Storage Gateway' }, { id: 'B', text: 'AWS DataSync — automated data transfer with bandwidth scheduling and parallel transfer to EFS/S3/FSx' }, { id: 'C', text: 'rsync over VPN' }, { id: 'D', text: 'AWS Snowball' }], correct: ['B'], explanation: 'DataSync uses parallel transfer protocols to move data 10x faster than traditional tools. Supports bandwidth limits per time window to avoid saturating production links. Integrates with EFS, S3, FSx, and on-premises NFS/SMB.', distractors: { A: 'Storage Gateway provides ongoing hybrid access — not a migration tool for bulk data transfer.', C: 'rsync is slow for 100 TB — no parallelism or bandwidth scheduling.', D: 'Snowball is for offline data transfer — useful when network bandwidth is insufficient, but DataSync is faster if bandwidth allows.' } },
  { id: 'd3-sto-014', domain: 3, topics: ['S3', 'intelligent tiering', 'cost'], type: 'single', stem: 'An S3 bucket stores 500 TB of objects with unknown access patterns. The team doesn\'t know which objects will be accessed and when. What storage class automatically optimizes cost without manual lifecycle policies?', options: [{ id: 'A', text: 'S3 Standard for all objects' }, { id: 'B', text: 'S3 Intelligent-Tiering — automatically moves objects between access tiers based on actual access patterns' }, { id: 'C', text: 'S3 Standard-IA for all objects' }, { id: 'D', text: 'S3 Glacier for all objects' }], correct: ['B'], explanation: 'S3 Intelligent-Tiering monitors access patterns and moves objects between Frequent Access, Infrequent Access, Archive Instant Access, and Archive tiers automatically. No manual lifecycle management needed. Small monthly monitoring fee per object.', distractors: { A: 'S3 Standard is costly for data that may rarely be accessed — no automatic optimization.', C: 'Standard-IA charges retrieval fees and assumes infrequent access — hot data becomes expensive.', D: 'Glacier requires restore before access — not suitable for data that might be accessed frequently.' } },
  { id: 'd3-sto-015', domain: 3, topics: ['EBS', 'io2', 'durability'], type: 'single', stem: 'A financial application requires the highest EBS volume durability. Which EBS volume type provides 99.999% (5 nines) durability?', options: [{ id: 'A', text: 'gp3 — 99.8-99.9% durability' }, { id: 'B', text: 'io2 and io2 Block Express — 99.999% durability (5 nines vs. 99.8-99.9% for other types)' }, { id: 'C', text: 'st1 — 99.999% durability' }, { id: 'D', text: 'All EBS volume types have the same durability' }], correct: ['B'], explanation: 'io2 volumes provide 99.999% durability (5 nines) — compared to 99.8-99.9% for gp3/gp2/io1/st1/sc1. The annual failure rate (AFR) for io2 is 0.001% vs. 0.1-0.2% for other types. Critical for databases requiring highest reliability.', distractors: { A: 'gp3 provides 99.8-99.9% durability — lower than io2.', C: 'st1 is HDD with the same 99.8-99.9% durability as gp — lower than io2.', D: 'EBS volume types have different durability levels — io2 is the highest.' } },
  { id: 'd3-sto-016', domain: 3, topics: ['FSx', 'Lustre', 'S3 integration'], type: 'single', stem: 'An ML training job reads training data from S3. The training cluster uses FSx for Lustre. How can FSx for Lustre efficiently access S3 data without copying everything first?', options: [{ id: 'A', text: 'All S3 data must be copied to FSx before training can begin' }, { id: 'B', text: 'Link FSx for Lustre to an S3 bucket — data is lazily loaded as needed and cached; write results back to S3' }, { id: 'C', text: 'Use DataSync to copy S3 to FSx daily' }, { id: 'D', text: 'FSx for Lustre doesn\'t integrate with S3' }], correct: ['B'], explanation: 'FSx for Lustre integrates natively with S3. When linked to an S3 bucket, files appear in FSx immediately (metadata visible) but are loaded from S3 on first access (lazy loading). After training, results can be synced back to S3. No full pre-copy needed.', distractors: { A: 'The S3 integration enables lazy loading — you don\'t need to copy all data upfront.', C: 'Daily DataSync is a manual process — the native S3 integration is automatic and more efficient.', D: 'FSx for Lustre has native S3 integration — it\'s one of its key features.' } },
  { id: 'd3-sto-017', domain: 3, topics: ['S3', 'requestor pays', 'performance bucket design'], type: 'single', stem: 'A company uploads 1 million small files (1 KB each) per hour to S3 using individual PUT requests. Costs are high due to request fees. What optimization reduces costs?', options: [{ id: 'A', text: 'Use Multipart Upload for 1 KB files' }, { id: 'B', text: 'Combine small files into larger aggregate files (packing) or use S3 batch operations — reduce per-request fees' }, { id: 'C', text: 'Switch to S3 Intelligent-Tiering' }, { id: 'D', text: 'Increase the S3 request limit' }], correct: ['B'], explanation: 'S3 charges per PUT request. 1 million requests per hour at $0.005/1000 = $5/hour. Packing small files into larger ones reduces the number of PUT requests dramatically. Alternatively, use S3 batch operations for bulk operations.', distractors: { A: 'Multipart upload is for large files (>100 MB) — using it on 1 KB files would add overhead, not reduce costs.', C: 'Storage class affects storage cost — not the per-request cost for PUT operations.', D: 'S3 request limits are service quotas — you can request increases but still pay per request.' } },
  { id: 'd3-sto-018', domain: 3, topics: ['EFS', 'access points'], type: 'single', stem: 'Multiple microservices share an EFS file system. Each service should only see and write to its own directory with its own POSIX user/group. What simplifies this access isolation?', options: [{ id: 'A', text: 'Create separate EFS file systems per service' }, { id: 'B', text: 'EFS Access Points — create per-service access points that enforce root directory and POSIX user/group identity' }, { id: 'C', text: 'Use POSIX file permissions on shared EFS directories' }, { id: 'D', text: 'Mount EFS with different IAM roles' }], correct: ['B'], explanation: 'EFS Access Points create application-specific entry points to an EFS file system. Each access point enforces: a root directory (service only sees its directory), a POSIX user and group (enforces ownership), and optionally overrides client root access.', distractors: { A: 'Separate file systems per service is expensive — EFS Access Points provide isolation within one file system.', C: 'POSIX permissions require proper user/group configuration on each client — Access Points enforce this server-side.', D: 'IAM roles control AWS API access — Access Points enforce file system path and POSIX identity.' } },
  { id: 'd3-sto-019', domain: 3, topics: ['S3', 'multipart copy', 'large objects'], type: 'single', stem: 'A company needs to copy a 100 GB object within S3 to a different bucket. What feature enables efficient copy?', options: [{ id: 'A', text: 'S3 CopyObject API (synchronous)' }, { id: 'B', text: 'S3 Multipart Upload copy using UploadPartCopy — copies in parallel parts up to 5 TB objects' }, { id: 'C', text: 'Download locally then upload' }, { id: 'D', text: 'S3 Batch Operations' }], correct: ['B'], explanation: 'For objects over 5 GB, use S3 multipart copy (UploadPartCopy). This breaks the object into parts and copies in parallel server-side. No data leaves AWS. Objects up to 5 GB can use the regular CopyObject API.', distractors: { A: 'CopyObject can be used for objects up to 5 GB — not 100 GB.', C: 'Downloading and re-uploading is inefficient — server-side copy keeps data within AWS.', D: 'S3 Batch Operations is for applying operations to many objects — not specifically for copying a single large object.' } },
  { id: 'd3-sto-020', domain: 3, topics: ['FSx', 'OpenZFS', 'performance'], type: 'single', stem: 'A development team needs a high-performance NFS file system with ZFS features (snapshots, clones, data compression) and sub-millisecond latency. Which FSx offering provides this?', options: [{ id: 'A', text: 'FSx for Lustre' }, { id: 'B', text: 'FSx for OpenZFS — ZFS-based, sub-millisecond latency, NFS, supports ZFS snapshots and clones' }, { id: 'C', text: 'FSx for Windows File Server' }, { id: 'D', text: 'Amazon EFS' }], correct: ['B'], explanation: 'FSx for OpenZFS provides ZFS-based file system with sub-millisecond latency, NFS support, built-in ZFS snapshots (instant clones), data compression, and up to 1 million IOPS. Suitable for dev/test, builds, and high-performance NFS workloads.', distractors: { A: 'FSx for Lustre is a parallel HPC file system — not ZFS-based.', C: 'FSx for Windows is SMB/Windows-focused — not ZFS.', D: 'EFS is general-purpose NFS — no ZFS features like instant clones or compression.' } },
  { id: 'd3-sto-021', domain: 3, topics: ['EBS', 'volume type migration', 'live'], type: 'single', stem: 'An application using gp2 EBS is experiencing performance limits. Can the volume be changed to gp3 or io2 without stopping the instance?', options: [{ id: 'A', text: 'No — volume type changes require stopping the instance' }, { id: 'B', text: 'Yes — EBS Elastic Volumes allows modifying volume type, IOPS, and throughput on live volumes without downtime' }, { id: 'C', text: 'Only volume size can be changed live — not type' }, { id: 'D', text: 'Only gp2 to gp3 is supported live — not to io2' }], correct: ['B'], explanation: 'EBS Elastic Volumes allows changing volume type (gp2 to gp3, io1, io2, etc.), size, IOPS, and throughput on a running instance without stopping or unmounting. Changes apply while the volume is in use.', distractors: { A: 'EBS modifications no longer require stopping the instance — Elastic Volumes enables live modification.', C: 'All volume attributes (type, size, IOPS, throughput) can be changed live.', D: 'All volume type changes are supported live with Elastic Volumes.' } },
  { id: 'd3-sto-022', domain: 3, topics: ['S3', 'batch operations', 'at scale'], type: 'single', stem: 'A company needs to change the storage class of 10 billion S3 objects to Glacier. Running the change manually would take months. What service handles this at scale?', options: [{ id: 'A', text: 'S3 Lifecycle rules (processes over time)' }, { id: 'B', text: 'S3 Batch Operations — runs operations on billions of objects efficiently using S3 Inventory as input' }, { id: 'C', text: 'AWS Lambda triggered by S3 events' }, { id: 'D', text: 'AWS CLI with --recursive flag' }], correct: ['B'], explanation: 'S3 Batch Operations runs actions (copy, restore, delete, change storage class, invoke Lambda, etc.) across billions of objects using an S3 Inventory report as the manifest. AWS manages the job execution, retries, and completion reporting.', distractors: { A: 'Lifecycle rules automate future transitions — they don\'t immediately process billions of existing objects.', C: 'Lambda triggered by events processes new uploads — not a bulk action on existing objects.', D: 'AWS CLI is slow for billions of objects and has no parallelism without custom scripting — S3 Batch Operations is purpose-built for this.' } },
  { id: 'd3-sto-023', domain: 3, topics: ['EBS', 'snapshot', 'archive tier'], type: 'single', stem: 'EBS snapshots older than 90 days are rarely needed. Storage costs are high. What EBS snapshot feature reduces costs for infrequently accessed snapshots?', options: [{ id: 'A', text: 'Delete old snapshots' }, { id: 'B', text: 'EBS Snapshot Archive — move snapshots to archive tier (75% cheaper) with 24-72 hour restore time' }, { id: 'C', text: 'Convert snapshots to S3 Glacier' }, { id: 'D', text: 'EBS snapshots cannot be tiered' }], correct: ['B'], explanation: 'EBS Snapshot Archive tier stores snapshots at ~75% lower cost than standard EBS snapshots. Restoring an archived snapshot takes 24-72 hours. Ideal for long-term compliance snapshots that are rarely needed.', distractors: { A: 'Deleting snapshots removes the ability to restore — archive tier preserves them at lower cost.', C: 'EBS snapshots are automatically stored in S3 (managed by AWS) — you can\'t directly manage them in S3 Glacier.', D: 'EBS Snapshot Archive tier is a real feature.' } },
  { id: 'd3-sto-024', domain: 3, topics: ['S3', 'SSE-C', 'customer keys'], type: 'single', stem: 'A company must manage their own encryption keys for S3 data and AWS must never have access to the keys. Which SSE option meets this requirement?', options: [{ id: 'A', text: 'SSE-S3 — AWS manages keys' }, { id: 'B', text: 'SSE-KMS — customer manages keys in KMS' }, { id: 'C', text: 'SSE-C — customer provides keys per request; AWS uses the key but never stores it' }, { id: 'D', text: 'Client-side encryption before upload' }], correct: ['C'], explanation: 'SSE-C (Server-Side Encryption with Customer-Provided Keys): the customer includes the encryption key in each S3 request. AWS uses the key to encrypt/decrypt but never stores it. The customer is responsible for key management.', distractors: { A: 'SSE-S3 uses AWS-managed keys — not customer-controlled.', B: 'SSE-KMS uses KMS where AWS does have access to decrypt (through KMS key policies) — the question says AWS must never have access.', D: 'Client-side encryption means encryption happens before upload and AWS never has the key or plaintext — valid but SSE-C is the native S3 server-side option.' } },
  { id: 'd3-sto-025', domain: 3, topics: ['Storage Gateway', 'tape gateway', 'backup'], type: 'single', stem: 'A company uses a physical tape library for backups. They want to eliminate physical tapes but keep the same backup software (Veeam, Commvault). What AWS service supports this?', options: [{ id: 'A', text: 'AWS Backup with Glacier' }, { id: 'B', text: 'AWS Storage Gateway Tape Gateway — virtual tape library (VTL) compatible with existing backup applications' }, { id: 'C', text: 'AWS DataSync' }, { id: 'D', text: 'S3 with backup software API' }], correct: ['B'], explanation: 'Tape Gateway presents a virtual tape library (VTL) interface — iSCSI virtual tapes compatible with all major backup software. Virtual tapes are stored in S3 and can be archived to S3 Glacier Deep Archive. No changes to backup software needed.', distractors: { A: 'AWS Backup supports multiple AWS services but doesn\'t present a VTL interface to legacy backup software.', C: 'DataSync is for data transfer/migration — not a VTL for backup software.', D: 'S3 APIs are not compatible with tape backup software without a translation layer — Tape Gateway provides that layer.' } },
  { id: 'd3-sto-026', domain: 3, topics: ['EBS', 'size limits'], type: 'single', stem: 'What is the maximum size of a single EBS volume?', options: [{ id: 'A', text: '1 TB' }, { id: 'B', text: '16 TB' }, { id: 'C', text: '64 TB — maximum for io2 Block Express and gp3' }, { id: 'D', text: '1 PB' }], correct: ['C'], explanation: 'The maximum EBS volume size is 64 TiB for io2 Block Express, gp3, gp2, io1, io2 standard. st1 and sc1 support up to 16 TiB. For most SSD types the maximum is 64 TiB.', distractors: { A: '1 TB is tiny — EC2 has supported multi-TB EBS volumes for years.', B: '16 TiB is the limit for st1/sc1 HDD volumes — not for SSD types like gp3 and io2.', D: 'EBS single volume maximum is 64 TiB — not 1 PB.' } },
  { id: 'd3-sto-027', domain: 3, topics: ['S3', 'versioning', 'lifecycle', 'cost'], type: 'single', stem: 'S3 versioning is enabled on a bucket. Multiple versions of objects accumulate and inflate storage costs. What lifecycle action removes old noncurrent versions after 30 days?', options: [{ id: 'A', text: 'NoncurrentVersionExpiration lifecycle action — delete versions after N days they became noncurrent' }, { id: 'B', text: 'S3 Intelligent-Tiering automatically removes noncurrent versions' }, { id: 'C', text: 'Disable versioning to remove old versions' }, { id: 'D', text: 'S3 Object Lock removes old versions automatically' }], correct: ['A'], explanation: 'NoncurrentVersionExpiration lifecycle rule permanently deletes noncurrent object versions after the configured number of days since they became noncurrent. Also use NewerNoncurrentVersions to keep the last N versions.', distractors: { B: 'Intelligent-Tiering manages storage class — not version deletion.', C: 'Disabling versioning stops creating new versions but doesn\'t delete existing ones (suspends, not removes).', D: 'Object Lock prevents deletion — the opposite of removing old versions.' } },
  { id: 'd3-sto-028', domain: 3, topics: ['EFS', 'lifecycle', 'One Zone'], type: 'single', stem: 'An EFS file system stores files that are infrequently accessed after 14 days. What reduces EFS storage costs for these files?', options: [{ id: 'A', text: 'EFS Standard storage class is always cheapest' }, { id: 'B', text: 'Enable EFS lifecycle management — files not accessed for 14 days transition to EFS Infrequent Access (EFS-IA), 90% cheaper' }, { id: 'C', text: 'Move files to S3 using Lambda' }, { id: 'D', text: 'Compress files to reduce storage' }], correct: ['B'], explanation: 'EFS Lifecycle Management automatically moves files to EFS-IA storage class based on access patterns (configurable: 7, 14, 30, 60, 90 days). EFS-IA is up to 92% cheaper than EFS Standard. Files are automatically moved back to Standard on access.', distractors: { A: 'EFS Standard is the most expensive tier — EFS-IA is significantly cheaper for infrequently accessed files.', C: 'Moving to S3 requires application changes and doesn\'t provide NFS access.', D: 'Compression reduces apparent storage but EFS charges for actual bytes stored.' } },
  { id: 'd3-sto-029', domain: 3, topics: ['S3', 'Glacier', 'restore', 'S3-class'], type: 'single', stem: 'A company restores a file from Glacier to S3 using Expedited retrieval. After the restore, they notice they\'re being charged for both Glacier and S3 Standard storage. Why?', options: [{ id: 'A', text: 'Expedited retrieval always deletes the Glacier copy' }, { id: 'B', text: 'Glacier restore creates a temporary copy in S3 Standard while the original remains in Glacier — the restored copy has a configurable TTL' }, { id: 'C', text: 'The data was moved to S3 Standard permanently' }, { id: 'D', text: 'This is a billing error' }], correct: ['B'], explanation: 'Glacier restore operations create a temporary copy in S3 Standard (or Reduced Redundancy). The original object stays in Glacier. The temporary copy has a defined TTL (1-365 days). After TTL, the S3 copy is deleted and only Glacier retains the data.', distractors: { A: 'Expedited retrieval creates a temporary copy — doesn\'t delete the Glacier original.', C: 'Glacier restore creates a temporary S3 copy — the original remains in Glacier.', D: 'This is expected behavior — the company should set an appropriate TTL for the restored copy.' } },
  { id: 'd3-sto-030', domain: 3, topics: ['EBS', 'RAID', 'performance'], type: 'single', stem: 'A database requires more IOPS than a single EBS volume can provide. Without using io2 Block Express, how can IOPS be increased?', options: [{ id: 'A', text: 'Increase the EBS volume size' }, { id: 'B', text: 'Configure RAID 0 across multiple EBS volumes — stripes I/O across volumes, multiplicatively increasing IOPS and throughput' }, { id: 'C', text: 'Use RAID 1 for better performance' }, { id: 'D', text: 'Attach multiple EBS volumes independently to the same instance' }], correct: ['B'], explanation: 'RAID 0 (striping) distributes data across multiple EBS volumes, combining their IOPS and throughput. 4 volumes with 16,000 IOPS each = 64,000 IOPS aggregate. Note: RAID 0 has no fault tolerance — a single volume failure loses all data.', distractors: { A: 'Increasing size increases gp3/gp2 storage but gp3 IOPS are independently provisioned up to 16,000 — not scalable beyond single volume limit.', C: 'RAID 1 (mirroring) provides redundancy — halves effective write IOPS compared to a single volume.', D: 'Attaching multiple volumes independently doesn\'t combine their IOPS for a single workload — RAID 0 stripes data across them.' } },
  { id: 'd3-sto-031', domain: 3, topics: ['S3', 'versioning', 'MFA delete', 'bucket lock'], type: 'single', stem: 'An S3 bucket stores critical data. To prevent accidental or unauthorized deletion, which combination provides the strongest protection?', options: [{ id: 'A', text: 'Versioning + S3 Object Lock (Compliance mode)' }, { id: 'B', text: 'Bucket policy Deny + MFA Delete + Versioning' }, { id: 'C', text: 'S3 Block Public Access' }, { id: 'D', text: 'S3 Lifecycle rules' }], correct: ['A'], explanation: 'S3 Object Lock Compliance mode + Versioning: objects cannot be deleted or modified by anyone (including root account) during the retention period. Combined, these provide WORM compliance — the strongest protection against deletion.', distractors: { B: 'Bucket policy + MFA Delete is strong but can potentially be bypassed by the root account — Compliance mode Object Lock cannot.', C: 'Block Public Access prevents public access — not deletion by authorized AWS principals.', D: 'Lifecycle rules can delete objects automatically — not a protection mechanism.' } },
  { id: 'd3-sto-032', domain: 3, topics: ['Storage Gateway', 'volume gateway', 'DR', 'EBS'], type: 'single', stem: 'A company uses Storage Gateway Volume Gateway (stored mode) for on-premises data. How can they use this for disaster recovery?', options: [{ id: 'A', text: 'Stored volumes are only accessible on-premises' }, { id: 'B', text: 'EBS snapshots of stored volumes are created in AWS — restore as EBS volumes and attach to EC2 instances for DR' }, { id: 'C', text: 'Volume Gateway only works for backup, not DR' }, { id: 'D', text: 'Clone the on-premises storage to the cloud manually' }], correct: ['B'], explanation: 'Storage Gateway stored volumes asynchronously snapshot to AWS as EBS snapshots. During DR, restore the latest EBS snapshot to a new EBS volume, attach to an EC2 instance, and access the data. This provides a cloud-based recovery point.', distractors: { A: 'Stored volumes are primarily on-premises but snapshots are in AWS for DR purposes.', C: 'DR via EBS snapshot recovery is a key use case for Volume Gateway stored mode.', D: 'Manual cloning is not needed — Gateway handles asynchronous snapshot creation.' } },
  { id: 'd3-sto-033', domain: 3, topics: ['S3', 'consistency', 'listing'], type: 'single', stem: 'An application writes objects to S3 and immediately lists the bucket to confirm they were written. Will the listing always return the newly written objects?', options: [{ id: 'A', text: 'No — S3 list operations are eventually consistent' }, { id: 'B', text: 'Yes — S3 provides strong consistency for all operations including list operations since December 2020' }, { id: 'C', text: 'Only if using S3 versioning' }, { id: 'D', text: 'Only for the first write — updates are eventually consistent' }], correct: ['B'], explanation: 'S3 strong read-after-write consistency (since December 2020) covers all operations: GET, PUT, DELETE, and LIST. Listing the bucket immediately after writing will reflect the newly written objects.', distractors: { A: 'This was true before December 2020 — S3 list operations are now strongly consistent.', C: 'Versioning doesn\'t affect consistency — it\'s available with or without versioning.', D: 'All S3 operations including overwrites and deletes are strongly consistent.' } },
  { id: 'd3-sto-034', domain: 3, topics: ['EBS', 'encryption', 'at rest'], type: 'single', stem: 'A new AWS account needs to ensure that ALL EBS volumes created in the account are encrypted by default. What setting enables this?', options: [{ id: 'A', text: 'Create a CloudWatch alarm for unencrypted EBS volumes' }, { id: 'B', text: 'Enable EBS encryption by default at the account/region level — all new EBS volumes are automatically encrypted' }, { id: 'C', text: 'Use AWS Config to enforce encryption' }, { id: 'D', text: 'Manually encrypt each volume at creation' }], correct: ['B'], explanation: 'EBS default encryption can be enabled per account per region. When enabled, all new EBS volumes are automatically encrypted using the default KMS key (or a custom CMK). Existing volumes are not retroactively encrypted.', distractors: { A: 'CloudWatch alarms can detect unencrypted volumes after the fact — not prevent unencrypted volumes from being created.', C: 'AWS Config detects non-compliant volumes and can auto-remediate — but EBS default encryption prevents creation of unencrypted volumes in the first place.', D: 'Manual encryption per volume is error-prone — default encryption is the automated solution.' } },
  { id: 'd3-sto-035', domain: 3, topics: ['EFS', 'security', 'IAM', 'NFS'], type: 'single', stem: 'An EFS file system should only allow access from EC2 instances with a specific IAM role. How is this enforced?', options: [{ id: 'A', text: 'POSIX file permissions control access' }, { id: 'B', text: 'EFS resource policy + IAM policy: grant elasticfilesystem:ClientMount to the specific role' }, { id: 'C', text: 'Security groups on EFS restrict to specific roles' }, { id: 'D', text: 'EFS doesn\'t support IAM-based access control' }], correct: ['B'], explanation: 'EFS supports IAM authorization for NFS clients. Configure an EFS resource-based policy allowing elasticfilesystem:ClientMount from specific IAM roles. Combined with the EC2 instance\'s IAM role, this ensures only authorized instances can mount the file system.', distractors: { A: 'POSIX permissions control file access within the mounted file system — not whether clients can mount it.', C: 'Security groups control network-level access (port 2049 NFS) — not IAM identity-based access.', D: 'EFS does support IAM-based access control since 2020.' } },
  { id: 'd3-sto-036', domain: 3, topics: ['S3', 'object tags', 'lifecycle', 'cost'], type: 'single', stem: 'A company stores files in S3. Files tagged with "archive=true" should be moved to Glacier after 30 days. How can this tag-based lifecycle be implemented?', options: [{ id: 'A', text: 'S3 Lifecycle rules don\'t support tag-based filtering' }, { id: 'B', text: 'Create an S3 Lifecycle rule with a tag filter: archive=true, transition to Glacier after 30 days' }, { id: 'C', text: 'Use a Lambda function triggered by S3 events' }, { id: 'D', text: 'Use S3 Batch Operations daily' }], correct: ['B'], explanation: 'S3 Lifecycle rules support filtering by object tags in addition to prefix. Configure a rule that matches objects with tag archive=true and transitions them to Glacier after 30 days from creation.', distractors: { A: 'S3 Lifecycle rules do support tag-based filtering — this is a valid and common use case.', C: 'Lambda-based lifecycle is possible but requires custom code and operational overhead — Lifecycle rules handle this natively.', D: 'Batch Operations runs one-time jobs — Lifecycle rules handle ongoing, automated transitions.' } },
  { id: 'd3-sto-037', domain: 3, topics: ['DataSync', 'S3 to S3', 'cross-region'], type: 'single', stem: 'A company needs to copy 50 TB of S3 data from one region to another with transfer validation (checksum verification). What service provides this efficiently?', options: [{ id: 'A', text: 'AWS CLI s3 sync command' }, { id: 'B', text: 'AWS DataSync — high-speed, validated data transfer between S3 locations with per-file checksum verification' }, { id: 'C', text: 'S3 Cross-Region Replication' }, { id: 'D', text: 'S3 Batch Operations with CopyObject' }], correct: ['B'], explanation: 'DataSync supports S3-to-S3 transfers with parallel processing, bandwidth controls, and built-in data integrity verification (checksums). For a one-time 50 TB migration with validation, DataSync is more appropriate than CRR (which is for ongoing replication).', distractors: { A: 'CLI s3 sync works but has no integrity verification, no bandwidth control, and is single-threaded without parallelism.', C: 'CRR is for continuous replication, not one-time migrations with checksums.', D: 'S3 Batch Operations CopyObject is fast but doesn\'t provide checksum verification per file.' } },
  { id: 'd3-sto-038', domain: 3, topics: ['EBS', 'direct APIs', 'snapshot'], type: 'single', stem: 'A backup application needs to read changed blocks from EBS snapshots programmatically without creating a volume. What API enables this?', options: [{ id: 'A', text: 'EBS snapshot must be mounted on EC2 to read blocks' }, { id: 'B', text: 'Amazon EBS direct APIs — ListSnapshotBlocks and GetSnapshotBlock for reading snapshots without creating volumes' }, { id: 'C', text: 'AWS DataSync' }, { id: 'D', text: 'Amazon S3 Glacier Restore' }], correct: ['B'], explanation: 'EBS direct APIs allow reading snapshot data directly: ListSnapshotBlocks (list all blocks in a snapshot), ListChangedBlocks (changed blocks between two snapshots), GetSnapshotBlock (read specific block data). No volume creation needed — ideal for backup software.', distractors: { A: 'EBS direct APIs specifically avoid the need to create a volume.', C: 'DataSync transfers file data — not EBS block-level snapshot data.', D: 'Glacier restore is for archiving S3 data — not EBS snapshot block access.' } },
  { id: 'd3-sto-039', domain: 3, topics: ['S3', 'performance', 'TCP', 'HTTP'], type: 'single', stem: 'A company transfers large files to S3 and wants to maximize throughput. The application uses a single TCP connection. What networking optimization should be applied?', options: [{ id: 'A', text: 'A single TCP connection maximizes S3 throughput' }, { id: 'B', text: 'Use S3 multipart upload with parallel part uploads — each part uses a separate TCP connection for maximum throughput' }, { id: 'C', text: 'Increase the TCP window size' }, { id: 'D', text: 'Use UDP instead of TCP' }], correct: ['B'], explanation: 'A single TCP connection is limited by latency and the TCP window size. Multipart upload allows each part to be uploaded in a separate HTTP request, effectively parallelizing the transfer and maximizing available bandwidth. More parallel connections = higher aggregate throughput.', distractors: { A: 'Single TCP connection throughput is limited by round-trip latency — parallelism is necessary for large file throughput.', C: 'TCP window size tuning helps but is complex — multipart parallel uploads are the recommended approach.', D: 'S3 doesn\'t support UDP — HTTP/HTTPS over TCP is the protocol.' } },
  { id: 'd3-sto-040', domain: 3, topics: ['FSx', 'Lustre', 'scratch vs persistent'], type: 'single', stem: 'An HPC job runs for 2 hours and needs a high-performance file system during execution. After the job, the data is exported to S3 and the file system can be deleted. What FSx for Lustre deployment type is most cost-effective?', options: [{ id: 'A', text: 'Persistent deployment type — high durability, replicates across AZs' }, { id: 'B', text: 'Scratch deployment type — temporary, no replication, highest performance, lowest cost, auto-deletes in 24 hours without activity' }, { id: 'C', text: 'Provisioned IOPS deployment type' }, { id: 'D', text: 'On-Demand deployment type' }], correct: ['B'], explanation: 'FSx for Lustre Scratch deployment is for temporary, short-term workloads. It provides the highest performance at lower cost (no data redundancy). For HPC jobs where data is imported from S3 and exported back when done, scratch is ideal.', distractors: { A: 'Persistent deployment stores data durably across AZ reboots — more expensive and unnecessary for temporary compute jobs.', C: 'There is no "Provisioned IOPS" FSx for Lustre type — scratch and persistent are the deployment types.', D: 'There is no specific "On-Demand" FSx for Lustre type.' } },
  { id: 'd3-sto-041', domain: 3, topics: ['S3', 'object expiration', 'lifecycle'], type: 'single', stem: 'A log bucket accumulates log files indefinitely. Logs older than 90 days are no longer needed. What lifecycle action removes them automatically?', options: [{ id: 'A', text: 'S3 Intelligent-Tiering automatically deletes old logs' }, { id: 'B', text: 'Create an S3 Lifecycle rule with Expiration action — objects expire and are deleted after 90 days' }, { id: 'C', text: 'S3 Object Lock prevents automatic deletion' }, { id: 'D', text: 'Set the maximum bucket storage limit' }], correct: ['B'], explanation: 'S3 Lifecycle Expiration rules automatically delete objects after a configured number of days from creation. For versioned buckets, use NoncurrentVersionExpiration and expired-object-delete-marker rules as well.', distractors: { A: 'Intelligent-Tiering manages storage class — not deletion.', C: 'Object Lock prevents deletion — the opposite of what\'s needed. Don\'t use it if you want to delete objects.', D: 'S3 has no configurable bucket size limit — objects must be explicitly deleted.' } },
  { id: 'd3-sto-042', domain: 3, topics: ['EBS', 'fast snapshot restore'], type: 'single', stem: 'A company frequently launches EC2 instances from snapshots for DR testing. The first few minutes after launch are slow because EBS blocks are loaded lazily from S3. What eliminates this warm-up period?', options: [{ id: 'A', text: 'Pre-warm the volume manually before each test' }, { id: 'B', text: 'Enable EBS Fast Snapshot Restore (FSR) — pre-initializes blocks so volumes restored from snapshots perform at full IOPS immediately' }, { id: 'C', text: 'Use instance store instead of EBS' }, { id: 'D', text: 'Use a larger EBS volume size' }], correct: ['B'], explanation: 'Fast Snapshot Restore pre-warms blocks in specific AZs so that volumes restored from enabled snapshots are immediately at full IOPS. No lazy initialization. Especially useful for frequently used golden AMIs and DR testing.', distractors: { A: 'Manual pre-warming (running dd commands) works but requires time after each launch — FSR eliminates this.', C: 'Instance store doesn\'t persist — can\'t be restored from a snapshot.', D: 'Volume size affects IOPS (for gp2) but doesn\'t eliminate lazy initialization.' } },
  { id: 'd3-sto-043', domain: 3, topics: ['S3', 'versioning', 'delete marker', 'lifecycle'], type: 'single', stem: 'A versioned S3 bucket is accumulating delete markers for objects that have no remaining versions. These expired delete markers waste storage. What lifecycle action removes them?', options: [{ id: 'A', text: 'NoncurrentVersionExpiration' }, { id: 'B', text: 'Expiration with expired-object-delete-marker set to true — removes delete markers when no other versions remain' }, { id: 'C', text: 'Abort incomplete multipart uploads' }, { id: 'D', text: 'Transition to Glacier' }], correct: ['B'], explanation: 'The lifecycle Expiration action with "expired-object-delete-marker" enabled automatically removes delete markers when there are no remaining noncurrent versions for that object key. This cleans up accumulated delete markers.', distractors: { A: 'NoncurrentVersionExpiration deletes non-current object versions — not delete markers.', C: 'Abort incomplete multipart uploads cleans up incomplete upload parts — unrelated to delete markers.', D: 'Transition moves objects to cheaper storage — doesn\'t clean up delete markers.' } },
  { id: 'd3-sto-044', domain: 3, topics: ['Transfer Family', 'SFTP', 'S3'], type: 'single', stem: 'Business partners send files via SFTP. The company wants to store received files in S3 without changing the partners\' SFTP workflow. What service bridges SFTP and S3?', options: [{ id: 'A', text: 'EC2 instance running an SFTP server' }, { id: 'B', text: 'AWS Transfer Family for SFTP — managed SFTP service that stores/retrieves files in S3 or EFS' }, { id: 'C', text: 'S3 doesn\'t support SFTP' }, { id: 'D', text: 'AWS DataSync' }], correct: ['B'], explanation: 'AWS Transfer Family provides managed SFTP (also FTPS, FTP, AS2) endpoints. Partners upload via standard SFTP — files are stored directly in S3 or EFS. No server management required, supports custom domains and identity providers (AD, LDAP).', distractors: { A: 'EC2 SFTP server works but requires maintenance, patching, HA configuration, and key management.', C: 'S3 doesn\'t natively support SFTP — Transfer Family is the bridge.', D: 'DataSync is for bulk data migration/replication — not an ongoing SFTP endpoint.' } },
  { id: 'd3-sto-045', domain: 3, topics: ['S3', 'VPC endpoint', 'gateway endpoint'], type: 'single', stem: 'EC2 instances in a private subnet need to access S3 without going through the internet or NAT Gateway. What provides free, private S3 access from a VPC?', options: [{ id: 'A', text: 'Internet Gateway' }, { id: 'B', text: 'S3 interface endpoint (PrivateLink)' }, { id: 'C', text: 'S3 Gateway Endpoint — free VPC endpoint for S3, routes traffic within AWS network via route table' }, { id: 'D', text: 'NAT Gateway with S3 IP routes' }], correct: ['C'], explanation: 'S3 Gateway Endpoints are free and provide VPC instances private access to S3 without NAT Gateways or internet. Traffic stays on the AWS network. Configure a route in the VPC route table pointing S3 prefixes to the gateway endpoint.', distractors: { A: 'Internet Gateway provides public internet access — instances in private subnets don\'t use IGW.', B: 'Interface endpoints (PrivateLink) for S3 exist but have an hourly charge — Gateway endpoints are free and should be preferred.', D: 'NAT Gateway has data processing charges — S3 gateway endpoint eliminates the cost.' } },
]
